() => {
  const card = document.getElementById('card');
  const cb = card.getBoundingClientRect();
  const cs = getComputedStyle(card);
  const pad = { t: parseFloat(cs.paddingTop), r: parseFloat(cs.paddingRight), b: parseFloat(cs.paddingBottom), l: parseFloat(cs.paddingLeft) };
  const inner = { l: cb.left + pad.l, r: cb.right - pad.r, t: cb.top + pad.t, b: cb.bottom - pad.b };
  const sel = ['.brand', '.avatar', '.sname', '.srole', '.eyebrow', '.title', '.footer', '.meta', '.cta'];
  const out = {};
  for (const s of sel) {
    const e = document.querySelector(s);
    if (!e) { out[s] = 'MISSING'; continue; }
    const r = e.getBoundingClientRect();
    out[s] = {
      x: Math.round(r.left - cb.left), y: Math.round(r.top - cb.top),
      w: Math.round(r.width), h: Math.round(r.height),
      overflowL: +(inner.l - r.left).toFixed(1) > 0.5 ? +(inner.l - r.left).toFixed(1) : 0,
      overflowR: +(r.right - inner.r).toFixed(1) > 0.5 ? +(r.right - inner.r).toFixed(1) : 0,
      overflowT: +(inner.t - r.top).toFixed(1) > 0.5 ? +(inner.t - r.top).toFixed(1) : 0,
      overflowB: +(r.bottom - inner.b).toFixed(1) > 0.5 ? +(r.bottom - inner.b).toFixed(1) : 0,
      clippedText: e.scrollWidth > e.clientWidth + 1 || e.scrollHeight > e.clientHeight + 1
    };
  }
  const t = document.querySelector('.title');
  const lh = parseFloat(getComputedStyle(t).lineHeight);
  const av = document.querySelector('.avatar').getBoundingClientRect();
  return {
    docScroll: { w: document.documentElement.scrollWidth, h: document.documentElement.scrollHeight },
    cardScroll: { w: card.scrollWidth, h: card.scrollHeight, cw: card.clientWidth, ch: card.clientHeight },
    font: document.fonts.check('700 60px Inter'),
    titleLines: Math.round(t.getBoundingClientRect().height / lh),
    avatarSquare: Math.abs(av.width - av.height) < 0.5,
    innerWidth: Math.round(inner.r - inner.l),
    gapTitleToFooter: Math.round(document.querySelector('.footer').getBoundingClientRect().top - t.getBoundingClientRect().bottom),
    el: out
  };
}

() => {
  const t = document.querySelector('.title');
  const r = document.createRange();
  r.selectNodeContents(t);
  const rects = [...r.getClientRects()].map(x => ({x: Math.round(x.x), w: Math.round(x.width), y: Math.round(x.y), h: Math.round(x.height)}));
  return { sw: t.scrollWidth, cw: t.clientWidth, sh: t.scrollHeight, ch: t.clientHeight, ow: t.offsetWidth, rects };
}

