() => {
  const t = document.querySelector('.title');
  const res = [];
  for (const fs of [68,72,74,76,78,80,84]) {
    t.style.fontSize = fs + 'px';
    const lh = parseFloat(getComputedStyle(t).lineHeight);
    const rng = document.createRange(); rng.selectNodeContents(t);
    const rects = [...rng.getClientRects()].filter(r=>r.width>0);
    const lines = Math.round((Math.max(...rects.map(r=>r.bottom)) - Math.min(...rects.map(r=>r.top)))/lh);
    // widest line vs available width
    const avail = t.getBoundingClientRect().width;
    const tops = [...new Set(rects.map(r=>Math.round(r.top)))];
    const lineW = tops.map(y => {
      const rs = rects.filter(r=>Math.round(r.top)===y);
      return Math.round(Math.max(...rs.map(r=>r.right)) - Math.min(...rs.map(r=>r.left)));
    });
    res.push({fs, lines, avail: Math.round(avail), lineW, blockH: Math.round(t.getBoundingClientRect().height)});
  }
  t.style.fontSize = '';
  return res;
}

