input.function:
() => {
  const t = document.querySelector('.title');
  const res = [];
  for (const fs of [68,70,72,74,76]) {
    t.style.fontSize = fs + 'px';
    const lh = parseFloat(getComputedStyle(t).lineHeight);
    const rng = document.createRange(); rng.selectNodeContents(t);
    const rects = [...rng.getClientRects()].filter(r=>r.width>0);
    const top0 = Math.min(...rects.map(r=>r.top));
    const lines = Math.round((Math.max(...rects.map(r=>r.bottom)) - top0)/lh);
    const avail = Math.round(t.getBoundingClientRect().width);
    // reconstruct text per visual line
    const walker = document.createTreeWalker(t, NodeFilter.SHOW_TEXT);
    const byLine = {};
    let n;
    while ((n = walker.nextNode())) {
      for (let i = 0; i < n.length; i++) {
        const r2 = document.createRange(); r2.setStart(n, i); r2.setEnd(n, i+1);
        const rr = r2.getBoundingClientRect();
        if (!rr.height) continue;
        const li = Math.round((rr.top - top0) / lh);
        (byLine[li] = byLine[li] || []).push(n.data[i]);
      }
    }
    res.push({fs, lines, avail, text: Object.keys(byLine).sort((a,b)=>a-b).map(k=>byLine[k].join(''))});
  }
  t.style.fontSize = '';
  return res;
}

